package com.shouxin.qa.audit;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin/operation-logs") @PreAuthorize("hasAnyRole('QA_ADMIN','SYS_ADMIN')") public class OperationLogController{private final JdbcTemplate jdbc;public OperationLogController(JdbcTemplate j){jdbc=j;}@GetMapping public Map<String,Object> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int pageSize,@RequestParam(required=false)String type){int size=Math.min(Math.max(pageSize,1),200),off=Math.max(page-1,0)*size;String base=" FROM sys_operation_log l LEFT JOIN sys_user u ON u.id=l.operator_id WHERE 1=1";List<Object>a=new ArrayList<>();if(type!=null&&!type.isBlank()){base+=" AND l.operation_type=?";a.add(type);}Integer total=jdbc.queryForObject("SELECT COUNT(*)"+base,Integer.class,a.toArray());String sql="SELECT l.id,l.operation_type,l.operation_content,l.target_type,l.target_id,l.client_ip,l.created_at,u.real_name"+base+" ORDER BY l.created_at DESC LIMIT ? OFFSET ?";a.add(size);a.add(off);return Map.of("items",jdbc.queryForList(sql,a.toArray()),"total",total==null?0:total,"page",page,"pageSize",size);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('SYS_ADMIN')") public void delete(@PathVariable String id){if(jdbc.update("DELETE FROM sys_operation_log WHERE id=?",id)!=1)throw new NoSuchElementException("日志不存在");}}
